UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Alfalfa</strong> (Medicago sativa) is a highly <strong>nutritive</strong>, <strong>mineralizing</strong>, <strong>diuretic</strong>, <strong>lymphatic</strong>, <strong>alterative</strong>, <strong>cardioprotective</strong>, <strong>anti-inflammatory</strong>, <strong>bone-building</strong>, and <strong>hypolipidemic</strong> legume-family herb that tastes salty; its roots penetrate 30 feet into the soil making it "chock full of minerals," and it contains <strong>phytosterols</strong>, <strong>inositol</strong>, B vitamins (B1, B2, B3, B5, B6, B9, B12), and <strong>chlorophyll</strong>. It is alkalizing to the <strong>gut</strong>, balances fluids, restores <strong>electrolytes</strong>, and nourishes the <strong>kidney</strong> and <strong>bladder</strong>; best extracted in water or vinegar over long periods (optimum steep 1-4 hours), and must be dried a rich green to be of good quality. It is a blood-building herb for cold constitution (with <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>) and indicated for a dry constitution (with <a href="?herb=43"><strong>Nettles</strong></a>, <a href="?herb=155"><strong>Red Raspberry</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>). The thyroid picture: moderate <strong>malabsorption</strong>, poor appetite, nervousness, weakness, poor nutritional status - <strong>nourishing</strong> for <strong>hormone regulation</strong>, <strong>cardioprotective</strong>, <strong>bone-building</strong>, and <strong>hypolipidemic</strong>. It supports <strong>calcium</strong> and <strong>potassium</strong> levels, builds <strong>bones</strong>, strengthens <strong>hair</strong> and <strong>teeth</strong>, supports <strong>hormonal regulation</strong> and <strong>estrogen</strong> pathways (as a legume), buffers blood in liver excess, and is indicated for <strong>anemia in pregnancy</strong>. It appears in the stress-depletion mineral formula (<a href="?herb=155"><strong>Raspberry Leaf</strong></a>, <a href="?herb=178"><strong>Oat Straw</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>), the inositol-rich tea blend for <strong>PMOS</strong>/fertility (<a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=1547"><strong>Kudzu</strong></a>), Fertili-Tea (<a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>), Legume Tea for Fertility, Iron Tonic Syrup for pregnancy (3 tablespoons), a nourishing post-menopausal tea (<a href="?herb=43"><strong>Nettles</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>), nourishing infusions with <a href="?herb=42"><strong>Red Clover</strong></a> for <strong>thyroid</strong>/<strong>Hashimoto's</strong> support, a herbal salt recipe, and a nutritive oxymel (<a href="?herb=43"><strong>Nettles</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a>, <strong>Seaweed</strong>, <a href="?herb=178"><strong>Oat Straw</strong></a>); also in a topical spray for pet <strong>hot spots</strong> (<a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=81"><strong>St. John's Wort</strong></a>). Suggested as part of a morning routine as an <strong>alterative</strong>.$$ WHERE common_name = 'Alfalfa';
